import { createContext, useContext } from 'react';
import { getJson, getJsonNow } from '../api/http';
import { asString, useSearchParam } from '../url/useSearchParam';

/** Set around a part of the screen that shows the sheets as they are now even while the screen shows the sheet as
 *  of a date (the consolidated figures). */
export const LiveFigures = createContext(false);

/** The query key and the read a sheet query uses: its own, or, inside {@link LiveFigures} while an as-of date is
 *  set, a key of its own ('live' first) read as the sheet is now. With no as-of date the two are the same query. */
export function useReadScope<K extends readonly unknown[]>(key: K): { key: readonly unknown[]; get: typeof getJson } {
  const live = useContext(LiveFigures);
  const [asof] = useSearchParam('asof', asString);
  return live && asof ? { key: ['live', ...key], get: getJsonNow } : { key, get: getJson };
}
package net.officefloor.hq.app.snapshot;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The snapshot lines of the people on a sheet: one per SNAPSHOT written for them, oldest first. */
@Repository
public class SnapshotLines {

    private static final RowMapper<SnapshotLine> ROW = (rs, i) -> new SnapshotLine(rs.getLong("person_id"),
            rs.getDate("left_day").toLocalDate().toString(), rs.getString("due_total"));

    private final JdbcTemplate jdbc;

    public SnapshotLines(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every snapshot line on the sheet, oldest first. */
    public List<SnapshotLine> list(String sheet) {
        return jdbc.query("SELECT person_id, left_day, due_total FROM person_snapshot WHERE sheet = ? ORDER BY id", ROW,
                sheet);
    }

    public void add(String sheet, long person, LocalDate day, String dueTotal) {
        jdbc.update("INSERT INTO person_snapshot (sheet, person_id, left_day, due_total) VALUES (?, ?, ?, ?)", sheet, person,
                Date.valueOf(day), dueTotal);
    }
}
package net.officefloor.hq.app.snapshot;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with every snapshot line on the sheet, oldest first. */
public class RespondWithSnapshotLines {
    public void respond(@PathVariable("sheet") String sheet, SnapshotLines lines,
            ObjectResponse<List<SnapshotLine>> response) {
        response.send(lines.list(sheet));
    }
}
