            }
            claims.unlockAll(sheet);
            // What the sheet holds at the end of its old today is kept, for a statement taken as of that date.
            states.keep(sheet, was, today);
            // Every row it holds is kept too, for the screen shown as of that date.
            snapshots.keep(sheet, was, today);
        }
        clock.setToday(sheet, today);
        // Periods past their grace days close before the figures the today change moved are audited.
        closer.autoClose(sheet, user);
        rollup.record(sheet, user, before);
    }
}
-- A person's snapshot lines: one per SNAPSHOT written for them as the sheet's today moved, with the day being left
-- and their due-total on it (two decimals, or n/a), listed oldest first (by id).
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet     VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    left_day  DATE         NOT NULL,
    due_total VARCHAR(40)  NOT NULL
);
CREATE INDEX person_snapshot_sheet ON person_snapshot (sheet, id);
